 return `${pageBanner('🧰','Teacher utilities','Classroom Tools','Launch common tools quickly without turning the page into a wall of buttons.','<button class="btn btn-primary btn-sm" data-page="seating">Open Seating Command & Room Builder</button>')}${migrated}${groups.map(g=>`<div class="section-heading"><div><div class="eyebrow">${g[0]}</div><h2>${g[0]}</h2></div></div><section class="tools-grid">${g[1].map(t=>`<article class="panel tool-card"><div class="tool-icon">${t[0]}</div><h3>${t[1]}</h3><p>${t[2]}</p><button class="btn btn-secondary btn-sm" data-tool="${t[1]}">Launch</button></article>`).join('')}</section>`).join('')}`;
