function aiUsagePage(){
 const today=state.operations?.academicAiUsage||{},month=state.operations?.academicAiUsageMonth||{},billing=state.operations?.openAiBillingSummary||{},models=Object.values(month.models||{}),outcomes=Object.values(month.outcomes||{}),money=value=>`$${Number(value||0).toFixed(4)}`,callsFor=name=>models.filter(row=>String(row.model||'').toLowerCase().includes(name)).reduce((sum,row)=>sum+Number(row.calls||0),0),luna=callsFor('luna'),terra=callsFor('terra'),sol=callsFor('sol'),monthCalls=Number(month.calls||0)+Number(month.focusedRetryCalls||0),todayCalls=Number(today.calls||0)+Number(today.focusedRetryCalls||0),estimated=Number(month.estimatedCostUsd||0),officialCurrent=billing.month===month.month&&Number.isFinite(Number(billing.officialCostUsd)),spend=officialCurrent?Number(billing.officialCostUsd):estimated,terraRate=monthCalls?terra/monthCalls*100:0,handled=outcomes.filter(row=>['approve','not_approved','complete'].includes(String(row.outcome))).reduce((sum,row)=>sum+Number(row.calls||0),0),waiting=outcomes.filter(row=>String(row.outcome)==='review').reduce((sum,row)=>sum+Number(row.calls||0),0),syncedMs=Number(billing.syncedAt?.seconds||0)*1000||Date.parse(String(billing.syncedAt||'')),syncLabel=officialCurrent&&syncedMs?new Date(syncedMs).toLocaleString():'Not synced',modelCard=(label,count,target,copy)=>`<article class="panel tool-card"><div class="eyebrow">${label.toUpperCase()}</div><h3>${count.toLocaleString()} calls</h3><progress class="dw-progress" max="${target}" value="${Math.min(target,count)}" aria-label="${label} usage">${count}</progress><p>${copy}</p></article>`,maxDaily=Math.max(1,...(month.days||[]).map(row=>Number(row.calls||0)+Number(row.focusedRetryCalls||0)));
 const exactModels=models.length?models.map(row=>`<tr><td>${escapeHtml(row.model||'Unknown model')}</td><td>${Number(row.calls||0).toLocaleString()}</td><td>${Number(row.inputTokens||0).toLocaleString()}</td><td>${Number(row.cachedInputTokens||0).toLocaleString()}</td><td>${Number(row.outputTokens||0).toLocaleString()}</td><td>${Number(row.reasoningTokens||0).toLocaleString()}</td><td>${money(row.estimatedCostUsd)}</td></tr>`).join(''):'<tr><td colspan="7">No model-level records yet. New calls will populate this table automatically.</td></tr>';
 const days=(month.days||[]).map(row=>{const calls=Number(row.calls||0)+Number(row.focusedRetryCalls||0);return `<div class="pass-card"><div class="row between"><b>${escapeHtml(row.dateKey)}</b><span>${calls} calls • ${money(row.estimatedCostUsd)}</span></div><progress class="dw-progress" max="${maxDaily}" value="${calls}" aria-label="${escapeHtml(row.dateKey)} calls">${calls}</progress></div>`}).join('')||'<p class="muted">No AI calls have been recorded this month.</p>';
 return `${pageBanner('🤖','Teacher-only operations','AI Usage & Billing','Dragonswood records each grading call locally; official OpenAI cost is synchronized only when you request it.',`<div class="row"><button class="btn btn-secondary btn-sm" type="button" data-manage-academic-ai>AI Settings</button><button class="btn btn-primary btn-sm" type="button" data-sync-openai-billing>↻ Sync official billing</button></div>`)}<section class="metric-grid">${metric('⚡','Today',todayCalls.toLocaleString(),'All AI grading stages')}${metric('📅','This month',money(spend),officialCurrent?'Official OpenAI cost':'Live Dragonswood estimate')}${metric('🌍','Terra escalation',`${terraRate.toFixed(1)}%`,`${terra} of ${monthCalls} calls`)}${metric('☀️','Sol ceiling',`${sol} / 25`,sol>=25?'Ceiling reached':'Monthly routing ceiling')}</section><article class="panel pass-card"><div class="row between"><div><div class="eyebrow">MONTHLY SPENDING CONTROL</div><h3>${money(spend)} of $5.00</h3><p>${spend>=5?'Limit reached':spend>=4?'Warning level reached':'Below the $4.00 warning level'} • ${officialCurrent?'Official cost':'Estimated cost'} • Last official sync: ${escapeHtml(syncLabel)}</p></div><span class="selected-badge">${Math.max(0,5-spend).toFixed(4)} remaining</span></div><progress class="dw-progress" max="5" value="${Math.min(5,spend)}" aria-label="Monthly AI spending">${spend}</progress></article><section class="grid-3 mt-12">${modelCard('Luna',luna,Math.max(1,monthCalls),'Primary low-cost route')}${modelCard('Terra',terra,Math.max(1,Math.ceil(monthCalls*.05)),'Escalation target near 5%')}${modelCard('Sol',sol,25,'Hard monthly ceiling: 25 calls')}</section><section class="metric-grid mt-12">${metric('✅','Reviews avoided',handled.toLocaleString(),'Approve, revise, or completed outcomes')}${metric('👀','Waiting for teacher',waiting.toLocaleString(),'Review outcomes still unresolved')}${metric('♻️','Cache hits',Number(month.cacheHits||0).toLocaleString(),'Responses reused without a new paid call')}${metric('🧠','Reasoning tokens',Number(month.reasoningTokens||0).toLocaleString(),'Recorded separately from output')}</section><section class="split-main mt-12"><article class="panel pass-list"><div class="section-heading no-top"><div><div class="eyebrow">DAILY ACTIVITY</div><h3>${escapeHtml(month.month||'Current month')}</h3></div></div><div class="stack">${days}</div></article><article class="panel pass-list"><div class="section-heading no-top"><div><div class="eyebrow">OFFICIAL BILLING</div><h3>${officialCurrent?money(billing.officialCostUsd):'Not synchronized'}</h3></div></div><p>${officialCurrent?'Organization cost total from OpenAI. Dragonswood request details remain in the local audit log.':'Add the server-only OPENAI_ADMIN_KEY secret, then use the sync button. No key is sent to this browser.'}</p><div class="stack">${Object.entries(billing.lineItems||{}).map(([label,value])=>`<div class="pass-card row between"><b>${escapeHtml(label)}</b><span>${money(value)}</span></div>`).join('')||'<div class="pass-card"><b>No official line items loaded.</b></div>'}</div></article></section><article class="panel gradebook-panel mt-12"><div class="section-heading"><div><div class="eyebrow">MODEL & TOKEN DETAIL</div><h3>Recorded by Dragonswood</h3></div></div><div style="overflow:auto"><table class="grade-table"><thead><tr><th>Model</th><th>Calls</th><th>Input</th><th>Cached input</th><th>Output</th><th>Reasoning</th><th>Estimated cost</th></tr></thead><tbody>${exactModels}</tbody></table></div></article>`;
}

