function playAttentionTone(loud=false){try{const Context=window.AudioContext||window.webkitAudioContext,ctx=new Context(),notes=loud?[659.25,987.77,1318.51]:[660,880];notes.forEach((frequency,index)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=loud?'triangle':'sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(loud ? 0.24 : 0.08,ctx.currentTime+index*.18);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+index*.18+(loud ? 0.42 : 0.25));osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime+index*.18);osc.stop(ctx.currentTime+index*.18+(loud ? 0.44 : 0.26))});setTimeout(()=>ctx.close(),loud?1300:700)}catch{}}
function startAmbientSound(){stopAmbientSound();try{const Context=window.AudioContext||window.webkitAudioContext;ambientContext=new Context();[174,261.63,349.23].forEach(frequency=>{const osc=ambientContext.createOscillator(),gain=ambientContext.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.value=.012;osc.connect(gain);gain.connect(ambientContext.destination);osc.start()});showToast('Calm classroom sound started.')}catch{showToast('Ambient sound is not available in this browser.')}}
function stopAmbientSound(){try{ambientContext?.close()}catch{}ambientContext=null;showToast('Ambient sound stopped.')}
